struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

VSOut VSMain(uint vid : SV_VertexID)
{
    VSOut o;
    o.uv = float2((vid << 1) & 2, vid & 2);
    o.pos = float4(o.uv * 2.0f - 1.0f, 0.0f, 1.0f);
    o.uv.y = 1.0f - o.uv.y;
    return o;
}

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

float hash(float n) { return frac(sin(n) * 43758.5453); }

float noise(float2 p)
{
    float2 i = floor(p);
    float2 f = frac(p);
    f = f * f * (3.0 - 2.0 * f);
    float n = i.x + i.y * 57.0;
    return lerp(lerp(hash(n), hash(n + 1.0), f.x),
                lerp(hash(n + 57.0), hash(n + 58.0), f.x), f.y);
}

float4 PSMain(VSOut i) : SV_Target
{
    float t = time_sim_ms * 0.001;
    float2 uv = i.uv;
    float3 sky = lerp(float3(0.0, 0.0, 0.05), float3(0.0, 0.02, 0.1), uv.y);
    float aurora = 0.0;
    for (int k = 0; k < 5; k++) {
        float freq = 2.0 + k * 0.7;
        float speed = 0.3 + k * 0.1;
        float wave = sin(uv.x * freq + t * speed + k * 1.5);
        wave += noise(float2(uv.x * 3.0 + t * 0.2, k * 10.0)) * 0.5;
        float band = smoothstep(0.0, 0.1, 0.1 - abs(uv.y - (0.5 + wave * 0.12)));
        aurora += band * (0.4 + 0.6 * noise(float2(uv.x * 5.0 + t, k * 7.0)));
    }
    aurora *= smoothstep(0.2, 0.6, uv.y) * smoothstep(1.0, 0.7, uv.y);
    float3 green = float3(0.1, 0.8, 0.3);
    float3 blue = float3(0.2, 0.3, 0.9);
    float3 auroraCol = lerp(green, blue, uv.y * 1.5);
    float3 col = sky + auroraCol * aurora * 0.8;
    return float4(col, 1.0);
}
